<?php
namespace App\Http\Controllers;use App\Http\Requests\StoreEmployerJobRequest;use App\Models\Company;use App\Models\EmployerProfile;use App\Models\Job;use App\Models\Technology;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class EmployerController extends Controller{public function dashboard(Request $r){$profile=$r->user()->employerProfile()->with('company')->first();$jobs=$r->user()->postedJobs()->withCount('applications')->latest()->paginate(15);return view('employer.dashboard',compact('profile','jobs'));}public function company(Request $r){$d=$r->validate(['name'=>'required|string|max:150','company_type'=>'required|in:company,recruitment_agency,consultancy,staffing_agency','website'=>'nullable|url|max:255','country'=>'required|string|max:100','designation'=>'nullable|string|max:100','phone'=>'nullable|string|max:30']);DB::transaction(function()use($r,$d){$c=Company::firstOrCreate(['slug'=>Str::slug($d['name'])],['name'=>$d['name'],'company_type'=>$d['company_type'],'website'=>$d['website']??null,'country'=>$d['country'],'is_active'=>true]);EmployerProfile::updateOrCreate(['user_id'=>$r->user()->id],['company_id'=>$c->id,'designation'=>$d['designation']??null,'phone'=>$d['phone']??null]);});return back()->with('success','Company profile saved.');}public function create(){return view('employer.job-form',['job'=>new Job]);}public function store(StoreEmployerJobRequest $r){$this->save(new Job,$r);return redirect()->route('employer.dashboard');}public function edit(Request $r,Job $job){$this->own($r,$job);return view('employer.job-form',compact('job'));}public function update(StoreEmployerJobRequest $r,Job $job){$this->own($r,$job);$this->save($job,$r);return redirect()->route('employer.dashboard');}public function close(Request $r,Job $job){$this->own($r,$job);$job->update(['status'=>'closed','is_active'=>false,'expires_at'=>now()]);return back();}private function own(Request $r,Job $j){abort_unless($r->user()->role==='admin'||$j->employer_id===$r->user()->id,403);}private function save(Job $j,StoreEmployerJobRequest $r){$p=$r->user()->employerProfile;abort_unless($p,422,'Create a company profile first.');$d=$r->validated();$skills=collect(explode(',',$d['skills']??''))->map(fn($v)=>trim($v))->filter()->unique()->take(30);$j->fill($d+['company_id'=>$p->company_id,'employer_id'=>$r->user()->id,'slug'=>Str::slug($d['title']).'-'.Str::lower(Str::random(7)),'status'=>$d['action']==='draft'?'draft':'pending','posting_source'=>'company','source'=>'employer','is_active'=>false,'requirements'=>$skills->values()->all()]);$j->save();$j->technologies()->sync($skills->map(fn($s)=>Technology::firstOrCreate(['slug'=>Str::slug($s)],['name'=>$s])->id));}}
